import csv
import io

def parse_csv(raw_csv: str):
    expected_width = 9
    delimiter = ","
    quotechar = '"'

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=delimiter,
        quotechar=quotechar,
        doublequote=True,
        escapechar=None,
        strict=False,
    )

    records = []
    try:
        for record in reader:
            records.append(record)
    except csv.Error:
        pass

    nonempty = [(index, record) for index, record in enumerate(records) if record]
    if not nonempty:
        return {
            "columns": ["column_{}".format(i) for i in range(1, expected_width + 1)],
            "rows": [],
        }

    header_index = None
    for index, record in nonempty:
        if len(record) == expected_width:
            header_index = index
            break

    if header_index is None:
        suitable = [
            (index, record)
            for index, record in nonempty
            if len(record) >= expected_width - 1
        ]
        if suitable:
            header_index = suitable[0][0]
        else:
            header_index = nonempty[0][0]

    def normalize(record):
        values = list(record)
        if len(values) < expected_width:
            values.extend([""] * (expected_width - len(values)))
        elif len(values) > expected_width:
            values = values[:expected_width - 1] + [
                delimiter.join(values[expected_width - 1:])
            ]
        return values

    columns = normalize(records[header_index])
    for index, value in enumerate(columns):
        if value == "":
            columns[index] = "column_{}".format(index + 1)

    rows = [
        normalize(record)
        for record in records[header_index + 1:]
    ]

    return {
        "columns": columns,
        "rows": rows,
    }
